            auto [r, c] = q.front();
            q.pop();
            for (int k = 0; k < 4; k++) take(r + dr[k], c + dc[k]);
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'O') board[i][j] = 'X';
                else if (board[i][j] == '#') board[i][j] = 'O';
            }
        }
    }
