public:
    long long minimumFuelCost(vector<vector<int>>& roads, int seats) {
        int n = (int)roads.size() + 1;
        vector<vector<int>> g(n);
        for (auto& e : roads) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        vector<int> parent(n, -1), order;
        order.reserve(n);
        parent[0] = 0;
        stack<int> st;
        st.push(0);
        while (!st.empty()) {
            int u = st.top();
            st.pop();
            order.push_back(u);
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                st.push(v);
            }
        }
        parent[0] = -1;
        vector<int> people(n, 1);
        long long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            if (u == 0) continue;
            int p = parent[u];
            people[p] += people[u];
            ans += (people[u] + seats - 1LL) / seats;
        }
        return ans;
    }
};

