    public int[][] findFarmland(int[][] land) {
        int m = land.length, n = land[0].length;
        List<int[]> ans = new ArrayList<>();
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (land[i][j] == 0) continue;
                int r2 = i, c2 = j;
                ArrayDeque<int[]> q = new ArrayDeque<>();
                land[i][j] = 0;
                q.add(new int[] {i, j});
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    r2 = Math.max(r2, cur[0]);
                    c2 = Math.max(c2, cur[1]);
                    for (int k = 0; k < 4; k++) {
                        int nr = cur[0] + dr[k], nc = cur[1] + dc[k];
                        if (nr < 0 || nr >= m || nc < 0 || nc >= n || land[nr][nc] == 0) continue;
                        land[nr][nc] = 0;
                        q.add(new int[] {nr, nc});
                    }
                }
                ans.add(new int[] {i, j, r2, c2});
            }
        }
        return ans.toArray(new int[0][]);
    }
}

