class Solution {
    public int[][] buildMatrix(int k, int[][] rowConditions, int[][] colConditions) {
        int[] row = topo(k, rowConditions);
        int[] col = topo(k, colConditions);
        if (row == null || col == null) return new int[0][0];
        int[] pr = new int[k + 1], pc = new int[k + 1];
        for (int i = 0; i < k; i++) {
            pr[row[i]] = i;
            pc[col[i]] = i;
        }
        int[][] mat = new int[k][k];
        for (int x = 1; x <= k; x++) mat[pr[x]][pc[x]] = x;
        return mat;
    }
