        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i <= k; i++) g.add(new ArrayList<>());
        int[] indeg = new int[k + 1];
        for (int[] c : cond) {
            g.get(c[0]).add(c[1]);
            indeg[c[1]]++;
        }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= k; i++) if (indeg[i] == 0) q.add(i);
        int[] order = new int[k];
        int p = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (p == k) return null;
            order[p++] = u;
            for (int v : g.get(u)) if (--indeg[v] == 0) q.add(v);
        }
        return p == k ? order : null;
    }
}

