class Solution:
    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:
        group = group[:]
        for i in range(n):
            if group[i] == -1:
                group[i] = m
                m += 1

        def topo(g: List[List[int]], indeg: List[int]) -> List[int]:
            q = deque([i for i in range(len(g)) if indeg[i] == 0])
            order = []
            while q:
                u = q.popleft()
                order.append(u)
                for v in g[u]:
                    indeg[v] -= 1
                    if indeg[v] == 0:
                        q.append(v)
            return order if len(order) == len(g) else []

        ig = [[] for _ in range(n)]
        gg = [[] for _ in range(m)]
        ii, gi = [0] * n, [0] * m
        for i in range(n):
            for pre in beforeItems[i]:
                ig[pre].append(i)
                ii[i] += 1
                if group[pre] != group[i]:
                    gg[group[pre]].append(group[i])
                    gi[group[i]] += 1
        item_ord, grp_ord = topo(ig, ii), topo(gg, gi)
        if not item_ord or not grp_ord:
            return []
        bucket = [[] for _ in range(m)]
        for item in item_ord:
            bucket[group[item]].append(item)
        ans = []
        for g in grp_ord:
            ans.extend(bucket[g])
        return ans

