from bisect import bisect_left
from typing import List

class SummaryRanges:
    def __init__(self):
        self.starts: List[int] = []
        self.end = {}

    def addNum(self, value: int) -> None:
        i = bisect_left(self.starts, value)
        if i < len(self.starts) and self.starts[i] == value:
            return
        if i > 0 and self.end[self.starts[i - 1]] >= value:
            return
        merge_left = i > 0 and self.end[self.starts[i - 1]] + 1 == value
        merge_right = i < len(self.starts) and self.starts[i] == value + 1
        start, end = value, value
        if merge_left:
            start = self.starts[i - 1]
        if merge_right:
            end = self.end[self.starts[i]]
            del self.end[self.starts[i]]
            self.starts.pop(i)
        if merge_left:
            self.end[start] = end
        else:
            self.starts.insert(i, start)
            self.end[start] = end

    def getIntervals(self) -> List[List[int]]:
        return [[s, self.end[s]] for s in self.starts]
